{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Subnet is not protected by a Network Security Group",
      "resource": "azurerm_subnet.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The data subnet has no associated Network Security Group, leaving subnet-level traffic controls unenforced. This increases the risk of unintended network access to healthcare data workloads deployed in the subnet."
    }
  ],
  "patched_code": "resource "azurerm_subnet" "data_subnet" {
  name                 = "healthcare-patient-portal-with-hipaa-compliance-subnet-data"
  resource_group_name  = azurerm_resource_group.healthcare_portal.name
  virtual_network_name = azurerm_virtual_network.healthcare_vnet.name
  address_prefixes     = ["10.0.3.0/24"]
}

resource "azurerm_network_security_group" "data_subnet" {
  name                = "healthcare-patient-portal-with-hipaa-compliance-nsg-data"
  location            = azurerm_resource_group.healthcare_portal.location
  resource_group_name = azurerm_resource_group.healthcare_portal.name
}

resource "azurerm_subnet_network_security_group_association" "data_subnet" {
  subnet_id                 = azurerm_subnet.data_subnet.id
  network_security_group_id = azurerm_network_security_group.data_subnet.id
}
",
  "fix_summary": "Added a Network Security Group and associated it with the data subnet. The NSG's default rules deny unsolicited inbound traffic not otherwise permitted."
}
